namespace sv_4ee4f6a8f9ad49b297d495841165d3aa.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";
    public string SelectedWarehouseName => Warehouses[SelectedWarehouseId];

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["warehouse-a"] = "Warehouse A — Main Distribution",
        ["warehouse-b"] = "Warehouse B — Regional Hub",
        ["warehouse-c"] = "Warehouse C — Cold Storage"
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_4ee4f6a8f9ad49b297d495841165d3aa.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query — return a random number between 0 and 15.
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    public async Task RefreshAsync(string warehouseId)
    {
        CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

