@page "/dashboard"
@using sv_4ee4f6a8f9ad49b297d495841165d3aa.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@Warehouse.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Site</h5>
                <p class="display-6">@Warehouse.SelectedWarehouseId</p>
                <p class="text-muted">Change via the top-bar dropdown</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="text-muted">Last refresh: @_lastRefresh.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime _lastRefresh = DateTime.Now;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to warehouse changes — refresh alerts immediately on switch.
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        Warehouse.OnChange += _warehouseHandler;

        // Subscribe to alert changes (fired by the service, updates all subscribers).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch.
        await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
        _lastRefresh = DateTime.Now;

        // Start polling every 10 seconds.
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
                    _lastRefresh = DateTime.Now;
                    StateHasChanged();
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

