                <p class="display-6">@Warehouse.SelectedWarehouseId</p>
                <p class="text-muted">Change via the top-bar dropdown</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
