@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime _lastRefresh = DateTime.Now;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to warehouse changes — refresh alerts immediately on switch.
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        Warehouse.OnChange += _warehouseHandler;

        // Subscribe to alert changes (fired by the service, updates all subscribers).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch.
        await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
        _lastRefresh = DateTime.Now;

        // Start polling every 10 seconds.
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAsync(Warehouse.SelectedWarehouseId);
                    _lastRefresh = DateTime.Now;
                    StateHasChanged();
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

